#!/usr/bin/env python3
"""
API Endpoint Permission Canonicalizer
Transforms API endpoint permission configuration into canonical form.
"""

import re
from collections import OrderedDict


def normalize_path_for_matching(path):
    """Normalize path for matching: replace all {var_name} with {var}."""
    return re.sub(r'\{[^}]+\}', '{var}', path)


def is_valid_method(method):
    """Check if method is valid."""
    valid_methods = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
    return method.upper() in valid_methods


def is_valid_permission(permission):
    """Check if permission is valid."""
    return permission.upper() in {'ALLOW', 'DENY'}


def is_valid_role(role):
    """Check if role is valid (non-empty alphanumeric with underscores and hyphens)."""
    return bool(role) and re.match(r'^[a-zA-Z0-9_-]+$', role)


def is_valid_path(path):
    """Check if path is valid (non-empty)."""
    return bool(path)


def parse_endpoints_section(lines):
    """
    Parse ENDPOINTS section.
    Returns (endpoints_dict, cutoff_occurred)
    endpoints_dict: dict mapping (normalized_path, method, role) -> (original_path, permission)
    """
    endpoints = OrderedDict()
    cutoff = False

    for line in lines:
        if cutoff:
            break
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 4:
            cutoff = True
            break

        path, method, role, permission = parts

        # Check path not empty
        if not path:
            cutoff = True
            break

        # Check method valid
        method_upper = method.upper()
        if not is_valid_method(method_upper):
            cutoff = True
            break

        # Check permission valid
        permission_upper = permission.upper()
        if not is_valid_permission(permission_upper):
            cutoff = True
            break

        # Check role not empty
        if not role:
            cutoff = True
            break

        # Role validation
        if not is_valid_role(role):
            cutoff = True
            break

        # Store endpoint
        norm_path = normalize_path_for_matching(path)
        key = (norm_path, method_upper, role)
        if key not in endpoints:
            endpoints[key] = (path, permission_upper)

    return endpoints, cutoff


def parse_base_exclude_section(lines):
    """
    Parse BASE/EXCLUDE section.
    Returns (base_path, excluded_roles)
    """
    base_path = None
    excluded_roles = set()

    for line in lines:
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if not parts:
            continue

        if parts[0] == 'base' and len(parts) >= 2:
            base_path = parts[1]
        elif parts[0] == 'exclude' and len(parts) >= 2:
            excluded_roles = set(parts[1:])

    return base_path, excluded_roles


def parse_plan_section(lines):
    """
    Parse PLAN section.
    Returns (plan_endpoints, cutoff_occurred)
    """
    plan = []
    cutoff = False

    for line in lines:
        if cutoff:
            break
        line = line.strip()
        if not line:
            continue

        parts = line.split()
        if len(parts) != 2:
            cutoff = True
            break

        path, method = parts

        if not path:
            cutoff = True
            break

        method_upper = method.upper()
        if not is_valid_method(method_upper):
            cutoff = True
            break

        plan.append((path, method_upper))

    return plan, cutoff


def is_parent_path(norm_parent, norm_child):
    """
    Check if norm_parent is a parent path of norm_child.
    Uses structural comparison: {var} is treated as wildcard matching any segment.
    """
    if norm_parent == norm_child:
        return False

    parent_parts = [p for p in norm_parent.split('/') if p]
    child_parts = [p for p in norm_child.split('/') if p]

    # Parent must be strictly shorter (has fewer segments)
    if len(parent_parts) >= len(child_parts):
        return False

    # Check prefix with wildcard matching: {var} matches any segment
    for i, (p, c) in enumerate(zip(parent_parts, child_parts)):
        if p != '{var}' and p != c:
            return False

    return True


def main():
    # Read input
    with open('/app/input.txt', 'r') as f:
        content = f.read()

    # Split into sections by empty lines
    lines = content.split('\n')
    sections = []
    current_section = []

    for line in lines:
        if line == '':
            if current_section:
                sections.append(current_section)
                current_section = []
        else:
            current_section.append(line)

    if current_section:
        sections.append(current_section)

    # Handle empty input
    if len(sections) == 0:
        with open('/app/output.txt', 'w') as f:
            f.write('\n')
        return

    # Parse sections
    endpoints_raw, endpoints_cutoff = parse_endpoints_section(sections[0])

    base_path = None
    excluded_roles = set()
    if len(sections) > 1:
        base_path, excluded_roles = parse_base_exclude_section(sections[1])

    plan_raw, plan_cutoff = parse_plan_section(sections[2] if len(sections) > 2 else [])

    plan_empty = len(plan_raw) == 0

    endpoint_lookup = endpoints_raw

    # Helper: check if path passes base filter
    def passes_base_filter(norm_path):
        if base_path is None:
            return True
        # Exact prefix match: norm_path must start with base_path
        return norm_path == base_path or norm_path.startswith(base_path + '/')

