    def is_in_plan(norm_path, method):
        for plan_path, plan_method in plan_raw:
            if normalize_path_for_matching(plan_path) == norm_path and plan_method == method:
                return True
        return False

    # Helper: check if endpoint's path is a parent of any PLAN path
    def is_on_parent_path(norm_path):
        for plan_path, _ in plan_raw:
            plan_norm = normalize_path_for_matching(plan_path)
            if is_parent_path(norm_path, plan_norm):
                return True
        return False

    if plan_empty:
        # Include all eligible endpoints (pass base filter, not excluded)
        include_keys = set()
        for key in endpoint_lookup.keys():
            norm_path, method, role = key
            if not passes_base_filter(norm_path):
                continue
            if role in excluded_roles:
                continue
            include_keys.add(key)
    else:
        # PLAN not empty: include endpoints that pass base filter AND (in_plan OR on_parent_path)
        include_keys = set()
        for key in endpoint_lookup.keys():
            norm_path, method, role = key
            if not passes_base_filter(norm_path):
                continue
            if is_in_plan(norm_path, method) or is_on_parent_path(norm_path):
                include_keys.add(key)

    # Sort by specificity
    def specificity_key(key):
        norm_path, method, role = key
        orig_path, perm = endpoint_lookup[key]
        segments = [s for s in orig_path.split('/') if s]
        seg_count = len(segments)
