        method_key = method_order.get(method, 999)
        role_key = role
        perm_key = 0 if perm == 'ALLOW' else 1
        return (-seg_count, method_key, role_key, perm_key)

    sorted_keys = sorted(include_keys, key=specificity_key)

    # Build output
    output_lines = []
    for key in sorted_keys:
        norm_path, method, role = key
        orig_path, perm = endpoint_lookup[key]
        output_lines.append(f"{orig_path} {method} {role} {perm}")

    # Write output
    with open('/app/output.txt', 'w') as f:
        if output_lines:
            f.write('\n'.join(output_lines) + '\n')
        else:
            f.write('\n')


if __name__ == '__main__':
    main()
